It seems like the configuration files you are trying to load are missing the 'configName' property. First, let's check the structure of your configuration files to ensure that they all contain this property. 

Here’s how to modify the `loader.js` to add a fallback if 'configName' is missing:

```javascript
const fs = require('fs');

function loadConfig(filePath) {
    const config = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    if (!config.configName) {
        throw new Error('Missing required property configName');
    }
    return config;
}

module.exports = loadConfig;
```

Also, add a test in your `configLoader.test.js` to cover this scenario:

```javascript
test('should throw error if configName is missing', () => {
    expect(() => loadConfig('./missingConfig.json')).toThrow('Missing required property configName');
});
```

Make sure to run your tests using Jest after making these changes to ensure everything is functioning correctly.
